// ============================================================
// === LUNAS WIRKUNG: ROTER SCHIMMER ===========================
// ============================================================
// - Ahne aus Profession: Aphasma oder Zerzal
// - Kreiszone mit 0,5 bis 4 Schritt Radius
// - maximaler Durchmesser: 8 Schritt
// - Mittelpunkt maximal 8 Schritt vom Wirkenden entfernt
// - einmal platzieren, danach nicht mehr bewegen
// - Sichtbarkeit der Fläche: 20 Prozent
// - Fläche ist ausschließlich eine visuelle Hilfe
// - GM wählt die tatsächlich betroffenen Token selbst aus
// - gültig: Erwachte und Tiere
// - Geister und andere Wesen erhalten keinen Effekt
// - jedes ausgewählte Ziel wird einzeln geprüft
// - gültige Ziele bleiben trotz ungültiger Ziele Erfolge
// - Willenskraft um QS × 2 FW erschwert
// - Jagdfieber: keine Willenskraft-Probe
// - Zieleffekt: Roter Schimmer (Ahne) - Jagdinstinkt
// - Quelleffekt vollständig über Block 6
// - Zieleffektanlage 1:1 wie Geisterbann über Block 17
// - dauerhafter GM-Zonenbutton über Block 11
// - Wirkungsende und Zonenbereinigung über Block 7 und Block 17
// ============================================================


// ============================================================
// === BLOCK 0 — WÄCHTER =======================================
// ============================================================

if (typeof args !== "undefined" && args[0] === "WeckerAufruf") {

    // +++ 0.1 - ZIELPRÜFUNG VOR DER EFFEKTANLAGE ++++++++++++++

    if (globalThis._dskRoterSchimmerZielPruefungHook) {
        Hooks.off("preCreateActiveEffect", globalThis._dskRoterSchimmerZielPruefungHook);
    }

    globalThis._dskRoterSchimmerZielPruefungHook = Hooks.on("preCreateActiveEffect", (effect, daten) => {
        const flagDaten = daten?.flags?.dsk || effect?.flags?.dsk || {};
        if (flagDaten.isRoterSchimmerZiel !== true) return;

        const targetActor = effect.parent;
        if (!targetActor) return false;

        const DSK_FW = globalThis.DSK;
        const type = String(targetActor.type || "").toLowerCase();
        const species = String(targetActor.system?.species?.value || targetActor.system?.details?.species || "").toLowerCase();
        const istGeist = type === "spirit" || ["geist", "spirit", "gespenst"].some(begriff => species.includes(begriff));

        const istErwacht = !istGeist && DSK_FW?.Effekt?.CheckTarget?.(targetActor, "erwachte") === true;
        const istTier = !istGeist && DSK_FW?.Wesen?.match?.(
            targetActor,
            ["tier", "tiere", "animal", "katze", "katzen"]
        ) === true;

        if (istErwacht || istTier) return;

        ui.notifications.warn(
            istGeist
                ? `Luna sagt 🌙: ${targetActor.name} ist ein Geist und kann den Effekt Jagdinstinkt nicht erhalten.`
                : `Luna sagt 🌙: ${targetActor.name} ist weder ein Erwachter noch ein Tier und kann den Effekt Jagdinstinkt nicht erhalten.`
        );

        return false;
    });

    // +++ 0.2 - JAGDFIEBER-WÄCHTER ++++++++++++++++++++++++++++

    if (globalThis._dskRoterSchimmerJagdfieberHook) {
        Hooks.off("createChatMessage", globalThis._dskRoterSchimmerJagdfieberHook);
    }

    globalThis._dskRoterSchimmerJagdfieberHook = Hooks.on("createChatMessage", async message => {
        if (message.speaker?.alias === "System" || message.flags?.dsk?.isWatcherMsg) return;

        const authorId = message.author?.id || message.user?.id;
        if (authorId !== game.user.id) return;

        const DSK_FW = globalThis.DSK;
        if (!DSK_FW) return;

        const text = DSK_FW.Schaden?.HtmlZuText
            ? DSK_FW.Schaden.HtmlZuText(`${String(message.flavor || "")} ${String(message.content || "")}`).toLowerCase()
            : `${String(message.flavor || "")} ${String(message.content || "")}`.toLowerCase();

        if (!text.includes("willenskraft")) return;

        const speaker = message.speaker || {};
        let rollActor = speaker.actor ? game.actors.get(speaker.actor) : null;
        if (!rollActor && speaker.token) rollActor = canvas.scene?.tokens?.get(speaker.token)?.actor || null;
        if (!rollActor) return;

        const roterSchimmer = (rollActor.effects || []).find(effect =>
            effect.getFlag("dsk", "isRoterSchimmerZiel") === true
        );

        if (!roterSchimmer) return;

        const hatJagdfieber = DSK_FW.Item?.HatGegenstand
            ? DSK_FW.Item.HatGegenstand(rollActor, "jagdfieber")
            : (rollActor.items || []).some(item =>
                String(item.name || "").toLowerCase().includes("jagdfieber")
            );

        if (!hatJagdfieber) return;

        const empfaenger = DSK_FW.Empfaenger?.GMUndBesitzer?.(
            rollActor,
            { anfragenderUserId: authorId }
        ) || [...new Set([
            ...game.users.filter(user => user.isGM).map(user => user.id),
            authorId
        ])].filter(id => game.users.get(id));

        await ChatMessage.create({
            whisper: empfaenger,
            speaker: { alias: "System" },
            flags: { dsk: { isWatcherMsg: true, roterSchimmerJagdfieber: true } },
            content: `<div style="font-family:'Signika',sans-serif;">
                ${DSK_FW.UI.Header(
                    "Jagdfieber blockiert Probe",
                    roterSchimmer.icon || roterSchimmer.img || DSK_FW.Symbol("Zerzal")
                )}
                <div class="dskbox2" style="margin-top:10px;text-align:center;">
                    <p style="font-weight:bold;font-size:1.1em;">${DSK_FW.ResolveTokenName(rollActor)}</p>
                    <hr style="margin:8px 0;border:0;border-top:1px solid #c9bca6;">
                    <p>Das Ziel steht unter dem Einfluss des <b>Roten Schimmers</b> und besitzt <b>Jagdfieber</b>. Der Jagdinstinkt wird übermächtig.</p>
                    <p style="color:#8b0000;font-weight:bold;">Die Willenskraft-Probe darf nicht abgelegt werden und gilt als automatisch gescheitert.</p>
                </div>
            </div>`
        });
    });

    return;
}


// ============================================================
// === NORMALE AUSFÜHRUNG ======================================
// ============================================================

(async function () {

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Zone ||
        !globalThis.DSK?.Effekt?.Anwenden ||
        !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Wesen?.match ||
        !globalThis.DSK?.Geometrie?.Distanz ||
        !globalThis.DSK?.GabenUI?.Details ||
        !globalThis.DSK?.GabenUI?.GMEffektBereich;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 250));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Zone ||
        !DSK_FW?.Effekt?.Anwenden ||
        !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Wesen?.match ||
        !DSK_FW?.Geometrie?.Distanz ||
        !DSK_FW?.GabenUI?.Details ||
        !DSK_FW?.GabenUI?.GMEffektBereich
    ) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Roter Schimmer";
    const endeKey = "roterSchimmer";
    const endeText = "Der rote Lichtpunkt erlischt und der Jagdinstinkt aller Betroffenen beruhigt sich wieder.";
    const minimalerRadius = 0.5, maximalerRadius = 4, maximaleReichweite = 8;

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }

        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenMessageId");
        }
    };

    const findeQuellEffekte = actor => (actor?.effects || []).filter(effect =>
        effect.getFlag("dsk", "isZoneSource") === true &&
        effect.getFlag("dsk", "isRoterSchimmerQuelle") === true &&
        effect.getFlag("dsk", "casterUuid") === actor.uuid
    );

    const templatePosition = templateDoc => ({
        center: {
            x: Number(
                canvas.templates?.placeables?.find(template =>
                    template.document?.id === templateDoc.id
                )?.center?.x ?? templateDoc.x
            ),
            y: Number(
                canvas.templates?.placeables?.find(template =>
                    template.document?.id === templateDoc.id
                )?.center?.y ?? templateDoc.y
            )
        }
    });

    // +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    const safeTestData = typeof testData !== "undefined" ? testData : null;
    const safeActor = typeof actor !== "undefined" ? actor : null;

    let casterActor =
        safeTestData?.actor ||
        (safeTestData?.speaker?.token ? canvas.tokens.get(safeTestData.speaker.token)?.actor : null) ||
        safeActor ||
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actorDoc => actorDoc?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actorDoc => actorDoc.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Kein Token des Wirkenden gefunden!");

    const profession = String(casterActor.system?.details?.profession || "").toLowerCase();
    const ahne = profession.includes("aphasma") ? "Aphasma" : "Zerzal";
    const vollerName = `${gabenName} (${ahne})`;
    const zielEffektName = `${vollerName} - Jagdinstinkt`;
    const iconBild = DSK_FW.Symbol(ahne);
    const casterName = DSK_FW.ResolveTokenName(casterActor);

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Roter Schimmer Probe", "Roter Schimmer"],
        testDataObj: safeTestData,
        fallback: 0,
        protokollieren: true
    });

    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    if (qs <= 0) {
        await ChatMessage.create({
            speaker: { alias: "System" },
            content: `${DSK_FW.UI.Header(vollerName, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="color:#B30000;text-align:center;"><b>Fehlschlag!</b></p>
                </div>`
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 5 - ZONENRADIUS KONFIGURIEREN +++++++++++++++++++++++

    const einstellungen = await foundry.applications.api.DialogV2.wait({
        window: { title: "Roten Schimmer konfigurieren" },
        position: { width: 420 },

        content: `<form><div style="font-family:'Signika',sans-serif;">
            ${DSK_FW.UI.Header(vollerName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="font-size:.95em;line-height:1.35;margin-bottom:10px;">
                    Lege die Größe der Zone fest, in der der rote Lichtpunkt umherwandert.
                </p>
                <label style="font-weight:bold;font-size:.9em;">Radius (0,5 bis 4 Schritt):</label>
                <input type="number" name="radius" value="4" min="0.5" max="4" step="0.5"
                    style="width:100%;padding:4px;margin-top:4px;">
                <p style="font-size:.85em;color:#555;margin:8px 0 0;">
                    Bei 4 Schritt Radius besitzt die Zone einen Gesamtdurchmesser von 8 Schritt.
                </p>
            </div>
        </div></form>`,

        buttons: [
            {
                action: "ok",
                label: "Weiter",
                icon: "fas fa-arrow-right",
                default: true,
                callback: event => {
                    const data = new FormData(event.target.closest("form"));

                    return {
                        radius: Math.min(
                            maximalerRadius,
                            Math.max(
                                minimalerRadius,
                                Number(data.get("radius")) || maximalerRadius
                            )
                        )
                    };
                }
            },
            {
                action: "cancel",
                label: "Abbrechen",
                icon: "fas fa-times",
                callback: () => null
            }
        ],

        rejectClose: false
    });

    if (!einstellungen) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Roter Schimmer abgebrochen.");
    }

    const zonenRadius = einstellungen.radius;

    // +++ 6 - ALTE EIGENE WIRKUNG ERSETZEN ++++++++++++++++++++

    const alteQuellEffekte = findeQuellEffekte(casterActor);

    if (alteQuellEffekte.length) {
        await casterActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            alteQuellEffekte.map(effect => effect.id)
        );
    }

    // +++ 7 - KREISZONE PLATZIEREN ++++++++++++++++++++++++++++

    const confirmPosition = () => foundry.applications.api.DialogV2.wait({
        window: { title: "Roten Schimmer platzieren" },
        position: { width: 420 },

        content: `<div style="font-family:'Signika',sans-serif;">
            ${DSK_FW.UI.Header(vollerName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="font-size:.95em;line-height:1.35;">
                    Verschiebe den Kreis mit <b>${zonenRadius} Schritt Radius</b> an die gewünschte Position.
                    <br><br>
                    Der Mittelpunkt darf maximal <b>${maximaleReichweite} Schritt</b> vom Wirkenden entfernt liegen.
                    <br><br>
                    Klicke danach auf <b>Position bestätigen</b>.
                </p>
            </div>
        </div>`,

        buttons: [
            {
                action: "ok",
                label: "Position bestätigen",
                icon: "fas fa-check",
                default: true,
                callback: () => true
            },
            {
                action: "cancel",
                label: "Abbrechen",
                icon: "fas fa-times",
                callback: () => false
            }
        ],

        rejectClose: false
    });

    ui.notifications.info("Luna sagt 🌙: Platziere die Zone des Roten Schimmers.");

    const templateData = {
        t: "circle",
        user: game.user.id,
        distance: zonenRadius,
        x: casterToken.center.x,
        y: casterToken.center.y,
        fillColor: "#b00000",
        fillAlpha: 0.20,
        borderColor: "#ff3030",
        lineThickness: 2,
        hidden: false
    };

    const createdTemplates = await canvas.scene.createEmbeddedDocuments(
        "MeasuredTemplate",
        [templateData]
    );

    const templateDoc = createdTemplates[0];

    if (!templateDoc) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Zone des Roten Schimmers konnte nicht erstellt werden!");
    }

    try {
        canvas.templates.activate();
    } catch (error) {}

    const positionBestaetigt = await confirmPosition();

    try {
        canvas.tokens.activate();
    } catch (error) {}

    if (!positionBestaetigt) {
        await templateDoc.delete();
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Roter Schimmer abgebrochen.");
    }

    const aktuelleZone = canvas.scene.templates?.get(templateDoc.id) || templateDoc;
    const reichweite = DSK_FW.Geometrie.Distanz(casterToken, templatePosition(aktuelleZone));

    if (!Number.isFinite(reichweite) || reichweite > maximaleReichweite) {
        await aktuelleZone.delete();
        await raeumeQSAuf(casterActor);

        return ui.notifications.warn(
            Number.isFinite(reichweite)
                ? `Luna sagt 🌙: Der Zonenmittelpunkt ist ${reichweite.toFixed(1)} Schritt entfernt. Erlaubt sind maximal ${maximaleReichweite} Schritt!`
                : "Luna sagt 🌙: Die Entfernung der Zone konnte nicht bestimmt werden!"
        );
    }

    // +++ 8 - WIRKUNGSDATEN +++++++++++++++++++++++++++++++++++

    const dauerKR = qs * 5;
    const erschwernisWillenskraft = qs * 2;

    const dauerText =
        `${dauerKR} KR ` +
        `<span style="font-weight:300;font-size:.9em;opacity:.8;">` +
        `(${qs} QS × 5)</span>`;

    const basisBeschreibung =
        `Das Ahnenkind erschafft eine kreisförmige Zone des Roten Schimmers ` +
        `mit ${zonenRadius} Schritt Radius.` +
        `<br><br>• Der Kreis besitzt einen Durchmesser von ${zonenRadius * 2} Schritt.` +
        `<br>• Erwachte und Tiere innerhalb der Zone können vom roten Licht abgelenkt werden.` +
        `<br>• Geister können nicht vom Roten Schimmer betroffen werden.` +
        `<br>• Willenskraft um ${erschwernisWillenskraft} FW erschwert.` +
        `<br>• Betroffene mit Jagdfieber dürfen keine Willenskraft-Probe ablegen.`;

    // +++ 9 - ZIELEFFEKT-DATEN 1:1 WIE GEISTERBANN ++++++++++++

    const effektData = {
        img: iconBild,
        duration: { rounds: dauerKR },

        changes: [
            {
                key: "system.skillModifiers.FW",
                mode: 0,
                value: `Willenskraft -${erschwernisWillenskraft}`,
                priority: 20
            }
        ],

        statuses: [],

        description:
            `Der rote Lichtpunkt weckt den Jagdinstinkt.` +
            `<br><br><b>Willenskraft:</b> ` +
            `-${erschwernisWillenskraft} FW.` +
            `<br><b>Jagdfieber:</b> Betroffene mit Jagdfieber ` +
            `dürfen keine Willenskraft-Probe ablegen.` +
            `<br><b>Wirkungsdauer:</b> ${dauerKR} KR.`,

        flags: {
            dsk: {
                isRoterSchimmerZiel: true,
                casterUuid: casterActor.uuid,
                casterName,
                qs,
                willenskraftMalus: erschwernisWillenskraft
            }
        }
    };

    // +++ 10 - QUELLEFFEKT 1:1 WIE GEISTERBANN ++++++++++++++++

    const quelleffekt = await casterActor.createEmbeddedDocuments(
        "ActiveEffect",
        [{
            name: vollerName,
            type: "base",
            icon: iconBild,
            img: iconBild,
            showIcon: 1,

            duration: {
                rounds: dauerKR
            },

            description: basisBeschreibung,

            flags: {
                dsk: {
                    isZoneSource: true,
                    isRoterSchimmerQuelle: true,
                    wirkungsendeUeberBlock6: true,
                    templateId: templateDoc.id,
                    templateUuid: templateDoc.uuid,
                    zielEffektName,
                    casterEffektName: vollerName,
                    casterUuid: casterActor.uuid,
                    casterName,
                    ahne,
                    qs,
                    zonenRadius,
                    maximaleReichweite,
                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        }]
    );

    if (!quelleffekt?.[0]) {
        await templateDoc.delete();
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Der Roter-Schimmer-Effekt konnte nicht angelegt werden!"
        );
    }

    // +++ 11 - GM-BEREICH 1:1 WIE GEISTERBANN +++++++++++++++++

    const gmHtml = DSK_FW.GabenUI.GMEffektBereich({
        templateId: templateDoc.id,
        zielEffektName,
        ahne,
        effektData,
        hinweis: "Wähle die betroffenen Erwachten und Tiere innerhalb der roten Zone aus."
    });

    if (!gmHtml?.includes("dsk-btn-apply")) {
        await quelleffekt[0].delete();
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Der Effekt-anwenden-Button konnte nicht erzeugt werden!"
        );
    }

    // +++ 12 - GEMEINSAME WIRKUNGSKARTE +++++++++++++++++++++++

    const successContent = `
        ${DSK_FW.UI.Header(vollerName, iconBild)}

        <div class="dskbox2" style="margin-top:10px;">
            ${DSK_FW.GabenUI.Details({
                titel: "Gabenwirkung Information",
                inhalt: basisBeschreibung,
                zentriert: true
            })}

            <hr>

            <p style="margin:0 0 4px;text-align:left;">
                <b>Wirkender:</b>
            </p>

            ${DSK_FW.UI.List([casterName])}

            <hr>

            <p style="text-align:center;margin-bottom:5px;">
                <b>Zonenradius:</b> ${zonenRadius} Schritt
            </p>

            <p style="text-align:center;margin-top:0;margin-bottom:5px;">
                <b>Gesamtdurchmesser:</b> ${zonenRadius * 2} Schritt
            </p>

            <p style="text-align:center;margin-bottom:0;">
                <b>Wirkungsdauer:</b> ${dauerText}
            </p>

            ${gmHtml}
        </div>`;

    // +++ 13 - KARTE AKTUALISIEREN 1:1 WIE GEISTERBANN ++++++++

    const msg = alteMessageId ? game.messages.get(alteMessageId) : null;

    if (msg) {
        await msg.update({
            content: successContent,
            whisper: [],

            "flags.dsk.gabenAnfrage": true,
            "flags.dsk.gabenName": vollerName,
            "flags.dsk.angewendet": false,
            "flags.dsk.anfragenderUserId": game.user.id
        });
    } else {
        await ChatMessage.create({
            speaker: { alias: "System" },

            flags: {
                dsk: {
                    gabenAnfrage: true,
                    gabenName: vollerName,
                    angewendet: false,
                    anfragenderUserId: game.user.id
                }
            },

            content: successContent
        });
    }

    // +++ 14 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

}).call(this);
